import { defineConfig } from 'vite';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));

// Every page is generated by scripts/build-site.mjs (see package.json prebuild); it lists them in pages.json.
const pages: string[] = existsSync(resolve(here, 'pages.json')) ? JSON.parse(readFileSync(resolve(here, 'pages.json'), 'utf8')) : ['index.html'];

export default defineConfig({
  base: process.env.VITE_BASE || './',
  build: {
    target: 'es2022',
    chunkSizeWarningLimit: 700,
    rollupOptions: { input: Object.fromEntries(pages.map((p) => [p.replace(/\/?index\.html$/, '') || 'index', resolve(here, p)])) },
  },
  server: { host: '127.0.0.1' },
});
